use std::io::{Read, Write};

fn emit(out: &mut Vec<u8>, data: &[u8], num: bool, n: &mut u64) {
    if !num {
        out.extend_from_slice(data);
        return;
    }
    let mut rest = data;
    while !rest.is_empty() {
        let (line, next) = match rest.iter().position(|&b| b == b'\n') {
            Some(i) => (&rest[..i], &rest[i + 1..]),
            None => (rest, &rest[rest.len()..]),
        };
        *n += 1;
        out.extend_from_slice(format!("{:6}\t", *n).as_bytes());
        out.extend_from_slice(line);
        out.push(b'\n');
        rest = next;
    }
}

fn main() {
    let mut num = false;
    let mut files = Vec::new();
    for a in std::env::args().skip(1) {
        if a == "-n" {
            num = true;
        } else {
            files.push(a);
        }
    }
    let mut out = Vec::new();
    let mut n = 0u64;
    let mut status = 0;
    if files.is_empty() {
        let mut d = Vec::new();
        let _ = std::io::stdin().read_to_end(&mut d);
        emit(&mut out, &d, num, &mut n);
    } else {
        for f in &files {
            match std::fs::read(f) {
                Ok(d) => emit(&mut out, &d, num, &mut n),
                Err(_) => {
                    out.extend_from_slice(format!("cat: {}: No such file\n", f).as_bytes());
                    status = 1;
                }
            }
        }
    }
    let so = std::io::stdout();
    let mut l = so.lock();
    let _ = l.write_all(&out);
    let _ = l.flush();
    std::process::exit(status);
}
